        .property:nth-child(2) { animation-delay: 0.13s; }
        .property:nth-child(3) { animation-delay: 0.20s; }
        .property:nth-child(4) { animation-delay: 0.27s; }
        @keyframes fadeInUp { to { opacity: 1; transform: translateY(0); } }

