        .progress-bar-value {
            height: 100%;
            border-radius: 5px;
            transition: width 1.06s cubic-bezier(0.25, 0.8, 0.25, 1);
            position: relative; will-change: width;
        }
        .progress-bar-value::after {
            content: ''; position: absolute; top: 0; right: 0; width: 4px; height: 100%;
