        .detox-status.detoxed { background: linear-gradient(135deg, #27ae60, #2ecc71); color: white; }
        .detox-status.detoxed::before { background: rgba(255, 255, 255, 0.2); animation: detoxRipple 3s infinite; }
        .detox-status.not-detoxed { background: linear-gradient(135deg, #8e44ad, #9b59b6); color: white; }
        .detox-status.not-detoxed::before { background: rgba(255, 255, 255, 0.15); animation: toxicRipple 4s infinite; }
        @keyframes detoxRipple { 0% { width: 0; height: 0; opacity: 0.8; } 100% { width: 100px; height: 100px; opacity: 0; } }
        @keyframes toxicRipple { 0% { width: 0; height: 0; opacity: 0.6; } 100% { width: 80px; height: 80px; opacity: 0; } }

        .season-display { font-size: 22px; font-weight: 600; position: relative; display: inline-block; }
        .season-spring { color: #27ae60; text-shadow: 0 2px 4px rgba(39, 174, 96, 0.3); }
        .season-spring::after { content: '🌸'; position: absolute; top: -5px; right: -25px; font-size: 16px; animation: floatSpring 4s ease-in-out infinite; }
        .season-summer { color: #f39c12; text-shadow: 0 2px 4px rgba(243, 156, 18, 0.3); }
        .season-summer::after { content: '☀️'; position: absolute; top: -5px; right: -25px; font-size: 16px; animation: rotateSummer 8s linear infinite; }
        .season-autumn { color: #e67e22; text-shadow: 0 2px 4px rgba(230, 126, 34, 0.3); }
        .season-autumn::after { content: '🍁'; position: absolute; top: -5px; right: -25px; font-size: 16px; animation: fallAutumn 6s ease-in-out infinite; }
        .season-winter { color: #3498db; text-shadow: 0 2px 4px rgba(52, 152, 219, 0.3); }
        .season-winter::after { content: '❄️'; position: absolute; top: -5px; right: -25px; font-size: 16px; animation: floatWinter 5s ease-in-out infinite; }
        @keyframes floatSpring { 0%, 100% { transform: translateY(0) rotate(0deg); } 50% { transform: translateY(-5px) rotate(10deg); } }
        @keyframes rotateSummer { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes fallAutumn { 0%, 100% { transform: translateY(0) translateX(0) rotate(0deg); } 25% { transform: translateY(3px) translateX(-2px) rotate(-15deg); } 75% { transform: translateY(-2px) translateX(2px) rotate(15deg); } }
        @keyframes floatWinter { 0%, 100% { transform: translateY(0) translateX(0); } 33% { transform: translateY(5px) translateX(-3px); } 66% { transform: translateY(-3px) translateX(3px); } }

        .blur-overlay {
