        .event-card {
            position: relative;
            background: linear-gradient(135deg, var(--bg-primary), var(--bg-secondary));
            border: 1px solid var(--border-color);
            border-radius: var(--corner-radius);
            padding: var(--spacing-m);
            transition: transform 0.2s ease, box-shadow 0.2s ease;
            overflow: hidden;
        }
        .event-card:hover { transform: translateY(-2px); box-shadow: 0 4px 12px var(--shadow-medium); }

        .ending-card {
            position: relative;
            background: linear-gradient(135deg, var(--bg-primary), var(--bg-secondary));
            border: 2px solid var(--accent-gold);
            border-radius: var(--corner-radius);
            padding: var(--spacing-m);
            transition: transform 0.2s ease, box-shadow 0.2s ease;
            overflow: hidden;
        }
        .ending-card:hover { transform: translateY(-2px); box-shadow: 0 6px 20px var(--shadow-medium); }
        .ending-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-gold), #f39c12, var(--accent-gold));
            opacity: 0.8;
        }

        .event-title, .ending-title {
            font-size: 16px;
            font-weight: 600;
            margin-bottom: var(--spacing-s);
            color: var(--text-primary);
            text-align: center;
