    </div>
</div>

<script>
    let allExpanded = false;
    let currentPage = 'status';

    const eventData = [
        { name: '第一次心动', requirement: 20 },
        { name: '梦中呓语', requirement: 30 },
        { name: '无意触碰', requirement: 50 },
        { name: '深夜求药', requirement: 70 },
        { name: '醉后真言', requirement: 90 },
        { name: '主动示好', requirement: 110 },
        { name: '雨夜相拥', requirement: 130 },
        { name: '坦白心意', requirement: 150 },
        { name: '解除婚约', requirement: 170 },
        { name: '生死相许', requirement: 180 }
    ];

    const endingData = [
        { name: '纯洁逃离' },
        { name: '愧疚自尽' },
        { name: '回归文修' },
        { name: '甘为侍妾' },
        { name: '香消玉殒' },
        { name: '盛大婚礼' }
    ];

    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) return defaultValue;
        if (Array.isArray(current)) {
            if (current.length > 0) {
                const actualValue = current[0];
                if (typeof actualValue === 'boolean') return actualValue;
                return String(actualValue);
            } else return defaultValue;
        }
        if (typeof current === 'boolean') return current;
        return String(current);
    }

    function switchPage(page) {
        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));

        document.getElementById(`page-${page}`).classList.add('active');
        event.target.classList.add('active');

        const title = document.getElementById('page-title');
        if (page === 'status') {
            title.textContent = '洛轻漪 · 状态面板';
        } else if (page === 'events') {
            title.textContent = '洛轻漪 · 事件概览';
        }

        currentPage = page;

        setTimeout(() => {
            updateAllSectionsState();
        }, 50);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);
        if (!valueMainDisplay) return;

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";
        const descriptionMatch = String(fullDisplayString).match(/\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
            descriptionText = descriptionMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim();
        }
        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
        if (valueMatch) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : parts[0].trim();
        } else if (!isNaN(parseFloat(fullDisplayString))) {
            numericValue = parseFloat(fullDisplayString);
            valueMainDisplay.innerText = fullDisplayString;
        } else {
            if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                numericValue = rawValueFromCharacterData[0];
                valueMainDisplay.innerText = String(numericValue);
            } else if (typeof rawValueFromCharacterData === 'number' || typeof rawValueFromCharacterData === 'string') {
                valueMainDisplay.innerText = String(rawValueFromCharacterData);
            } else {
                valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
            }
        }
        if (valueDescDisplay) valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            progressBar.style.backgroundColor = color ? color : 'var(--accent-highlight)';
        }
    }

    function toggleTheme() {
        const body = document.body;
        const currentTheme = body.getAttribute('data-theme');
        const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
        body.setAttribute('data-theme', newTheme);
        localStorage.setItem('theme', newTheme);
    }

    function initTheme() {
        const savedTheme = localStorage.getItem('theme') || 'light';
        document.body.setAttribute('data-theme', savedTheme);
    }

    function setSectionExpanded(headerEl, expand) {
        const content = headerEl.nextElementSibling;
        const panel = content ? content.querySelector('.section-panel') : null;
        const arrow = headerEl.querySelector('.section-arrow');
        if (!content || !panel || !arrow) return;

        const isExpanded = content.classList.contains('expanded');
        if (expand === isExpanded) return;

        const parentPage = headerEl.closest('.page');
        const isPageVisible = parentPage && parentPage.classList.contains('active');

        if (!isPageVisible) {
            if (expand) {
                content.classList.add('expanded');
                headerEl.classList.add('expanded-header');
                arrow.style.transform = 'rotate(180deg)';
                content.style.height = 'auto';
                content.style.opacity = '1';
            } else {
                content.classList.remove('expanded');
                headerEl.classList.remove('expanded-header');
                arrow.style.transform = 'rotate(0deg)';
                content.style.height = '0';
                content.style.opacity = '0';
            }
            return;
        }

        const easing = 'cubic-bezier(0.2, 0.8, 0.2, 1)';
        const heightDuration = 466;
        const opacityDuration = 333;

        content.style.transition = 'none';
        content.getBoundingClientRect();

        if (expand) {
            content.classList.add('expanded');
            headerEl.classList.add('expanded-header');
            arrow.style.transform = 'rotate(180deg)';

            content.style.height = '0px';
            content.style.opacity = '0';
            requestAnimationFrame(() => {
                const target = panel.scrollHeight;
                content.style.transition = `height ${heightDuration}ms ${easing}, opacity ${opacityDuration}ms ease`;
                content.style.height = target + 'px';
                content.style.opacity = '1';

                content.addEventListener('transitionend', function onEnd(e) {
                    if (e.propertyName === 'height') {
                        content.style.transition = '';
                        content.style.height = 'auto';
                        content.removeEventListener('transitionend', onEnd);
                    }
                });
            });
        } else {
            const start = content.offsetHeight;
            content.style.height = start + 'px';
            content.style.opacity = '1';
            requestAnimationFrame(() => {
                content.style.transition = `height ${heightDuration}ms ${easing}, opacity ${opacityDuration}ms ease`;
                content.style.height = '0px';
                content.style.opacity = '0';
            });

            content.addEventListener('transitionend', function onEnd(e) {
                if (e.propertyName === 'height') {
                    content.classList.remove('expanded');
                    headerEl.classList.remove('expanded-header');
                    arrow.style.transform = 'rotate(0deg)';
                    content.style.transition = '';
                    content.removeEventListener('transitionend', onEnd);
                }
            });
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const shouldExpand = !content.classList.contains('expanded');
        setSectionExpanded(element, shouldExpand);
        updateAllSectionsState();
    }

    function toggleAllSections() {
        const activePage = document.querySelector('.page.active');
        const sections = activePage.querySelectorAll('.section');
        const toggleText = document.getElementById('toggle-all-text');
        const toggleIcon = document.getElementById('toggle-all-icon');

        const expand = !allExpanded;
        sections.forEach(section => {
            const header = section.querySelector('.section-header');
            setSectionExpanded(header, expand);
        });

        allExpanded = expand;
        toggleText.textContent = allExpanded ? '全部收起' : '全部展开';
        toggleIcon.textContent = allExpanded ? '▲' : '▼';
    }

    function updateAllSectionsState() {
        const activePage = document.querySelector('.page.active');
        const sections = activePage.querySelectorAll('.section-content');
        const expandedCount = Array.from(sections).filter(s => s.classList.contains('expanded')).length;
        const toggleText = document.getElementById('toggle-all-text');
        const toggleIcon = document.getElementById('toggle-all-icon');

        allExpanded = expandedCount === sections.length;
        toggleText.textContent = allExpanded ? '全部收起' : '全部展开';
        toggleIcon.textContent = allExpanded ? '▲' : '▼';
    }

    function applyBlurOverlay(elementId, overlayText) {
        const element = document.getElementById(elementId);
        if (element) {
            element.style.position = 'relative';
            element.style.overflow = 'hidden';
            element.style.borderRadius = element.style.borderRadius || '12px';
            let overlay = element.querySelector('.blur-overlay');
            if (!overlay) {
                overlay = document.createElement('div');
                overlay.className = 'blur-overlay';
                element.appendChild(overlay);
            }
            overlay.textContent = overlayText;
            overlay.style.display = 'flex';
        }
    }

    function removeBlurOverlay(elementId) {
        const element = document.getElementById(elementId);
        if (element) {
            const overlay = element.querySelector('.blur-overlay');
            if (overlay) { overlay.style.display = 'none'; }
        }
    }

    function updateEventStatus(characterData) {
        eventData.forEach((event, index) => {
            const eventCard = document.getElementById(`event-${index + 1}`);
            const eventStatus = eventCard.querySelector('.event-status');
            const overlay = eventCard.querySelector('.blur-overlay');

            const eventTriggered = SafeGetValue(characterData, `事件.${event.name}`, 0);

            if (parseInt(eventTriggered) === 1) {
                eventStatus.textContent = '已触发';
                eventStatus.className = 'event-status triggered';
                overlay.style.display = 'none';
            } else {
                eventStatus.textContent = '未触发';
                eventStatus.className = 'event-status locked';
                overlay.style.display = 'flex';
            }
        });
    }

    function updateEndingStatus(characterData) {
        endingData.forEach((ending, index) => {
            const endingCard = document.getElementById(`ending-${index + 1}`);
            const endingStatus = endingCard.querySelector('.ending-status');
            const overlay = endingCard.querySelector('.blur-overlay');

            const endingTriggered = SafeGetValue(characterData, `事件.${ending.name}`, 0);

            if (parseInt(endingTriggered) === 1) {
                endingStatus.textContent = '已触发';
                endingStatus.className = 'ending-status triggered';
                overlay.style.display = 'none';
            } else {
                endingStatus.textContent = '未触发';
                endingStatus.className = 'ending-status locked';
                overlay.style.display = 'flex';
            }
        });
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                return;
            }

            const characterKey = "洛轻漪";
            const worldKey = "世界";
            const wenxiuKey = "邵文修";

            if (characterData.hasOwnProperty(characterKey)) {
                const detoxStatus = SafeGetValue(characterData, `${characterKey}.解毒状态`, false);
                const isDetoxed = detoxStatus === true || detoxStatus === 'true';

                const detoxStatusDisplay = document.getElementById('detox-status-display');
                const detoxStatusText = document.getElementById('detox-status-text');
                if (isDetoxed) {
                    detoxStatusDisplay.className = 'detox-status detoxed';
                    detoxStatusText.textContent = '已解毒';
                } else {
                    detoxStatusDisplay.className = 'detox-status not-detoxed';
                    detoxStatusText.textContent = '未解毒';
                }

                if (isDetoxed) {
                    const sanityProperty = document.getElementById('sanity-property');
                    if (sanityProperty) {
                        sanityProperty.innerHTML = '<div class="recovery-notice">理智已恢复正常</div>';
                    }
                    applyBlurOverlay('toxicity-property', '已解毒');
                    removeBlurOverlay('memory-property');
                } else {
                    updateProgressBar(
                        'sanity-bar','sanity-value','sanity-desc',
                        SafeGetValue(characterData, `${characterKey}.理智值`), 0, 100, 'var(--sanity-color)'
                    );
                    removeBlurOverlay('toxicity-property');
                    applyBlurOverlay('memory-property', '未解锁');
                }

                updateProgressBar(
                    'toxicity-bar','toxicity-value','toxicity-desc',
                    SafeGetValue(characterData, `${characterKey}.毒性值`), 0, 100, 'var(--toxicity-color)'
                );

                updateProgressBar(
                    'corruption-bar','corruption-value','corruption-desc',
                    SafeGetValue(characterData, `${characterKey}.沉沦值`), 0, 200, 'var(--corruption-color)'
                );

                updateProgressBar(
                    'memory-bar','memory-value','memory-desc',
                    SafeGetValue(characterData, `${characterKey}.记忆恢复度`), 0, 100, 'var(--memory-color)'
                );

            } else {
                const defaultElements = ['sanity-value', 'toxicity-value', 'corruption-value', 'memory-value'];
                defaultElements.forEach(id => {
                    const element = document.getElementById(id);
                    if (element) element.innerText = 'N/A';
                });

                const defaultBars = ['sanity-bar', 'toxicity-bar', 'corruption-bar', 'memory-bar'];
                defaultBars.forEach(id => {
                    const element = document.getElementById(id);
                    if (element) element.style.width = '0%';
                });
            }

            if (characterData.hasOwnProperty(wenxiuKey)) {
                updateProgressBar(
                    'awareness-bar','awareness-value','awareness-desc',
                    SafeGetValue(characterData, `${wenxiuKey}.察觉值`), 0, 100, 'var(--awareness-color)'
                );
            } else {
                const awarenessValue = document.getElementById('awareness-value');
                if (awarenessValue) awarenessValue.innerText = 'N/A';
                const awarenessBar = document.getElementById('awareness-bar');
                if (awarenessBar) awarenessBar.style.width = '0%';
            }

            if (characterData.hasOwnProperty(worldKey)) {
                const currentTime = document.getElementById('current-time');
                if (currentTime) currentTime.textContent = SafeGetValue(characterData, `${worldKey}.当前时间`, '00:00');

                const currentDate = document.getElementById('current-date');
                if (currentDate) currentDate.textContent = SafeGetValue(characterData, `${worldKey}.当前日期`, '1970-01-01');

                const daysCount = document.getElementById('days-count');
                if (daysCount) {
                    const days = SafeGetValue(characterData, `${worldKey}.时日`, '1');
                    daysCount.textContent = `第${days}天`;
                }

                const seasonDisplay = document.getElementById('season-display');
                if (seasonDisplay) {
                    const season = SafeGetValue(characterData, `${worldKey}.当前季节`, '春');
                    seasonDisplay.textContent = season;
                    seasonDisplay.className = `season-display season-${seasonMapping[season] || 'spring'}`;
                }
            }

            updateEventStatus(characterData);
            updateEndingStatus(characterData);

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    const seasonMapping = { '春': 'spring', '夏': 'summer', '秋': 'autumn', '冬': 'winter' };

    document.addEventListener('DOMContentLoaded', function () {
        initTheme();
        initDisplay();
    });
</script>
</body>
