<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>生活片段</title>
    <style>
        :root {
            --corner-radius: 12px;
            --spacing-xs: 6px;
            --spacing-s: 10px;
            --spacing-m: 14px;
            --spacing-l: 18px;
            --spacing-xl: 24px;

            --bg-card: #ffffff;
            --text-primary: #2c2c2c;
            --text-secondary: #666666;
            --border-color: #e0e0e0;
            --shadow-soft: rgba(0, 0, 0, 0.08);
            --shadow-medium: rgba(0, 0, 0, 0.12);
            --accent-gold: #d4af37;
            --accent-hover: #b8941f;
        }

        [data-theme="gray"] {
            --bg-card: #3a3f47;
            --text-primary: #d4d4d8;
            --text-secondary: #9ca3af;
            --border-color: #4b5563;
            --shadow-soft: rgba(0, 0, 0, 0.2);
            --shadow-medium: rgba(0, 0, 0, 0.3);
            --accent-gold: #e5c07b;
            --accent-hover: #d19a66;
        }

        [data-theme="dark"] {
            --bg-card: #2d2d2d;
            --text-primary: #e0e0e0;
            --text-secondary: #a0a0a0;
            --border-color: #404040;
            --shadow-soft: rgba(0, 0, 0, 0.3);
            --shadow-medium: rgba(0, 0, 0, 0.5);
            --accent-gold: #f1c40f;
            --accent-hover: #d4a00e;
        }

        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            font-family: 'Microsoft YaHei', sans-serif;
            color: var(--text-primary);
            padding: var(--spacing-l);
            transition: color 0.3s ease;
        }

        .life-snippet-container {
            max-width: 600px;
            margin: 0 auto;
            background: var(--bg-card);
            border-radius: var(--corner-radius);
            box-shadow: 0 4px 20px var(--shadow-soft);
            border: 1px solid var(--border-color);
            overflow: hidden;
            position: relative;
            transition: all 0.3s ease;
        }

        .life-snippet-container::before,
        .life-snippet-container::after {
            content: '';
            position: absolute;
            width: 16px;
            height: 16px;
            border-color: var(--accent-gold);
            opacity: 0.8;
            z-index: 5;
        }

        .life-snippet-container::before {
            top: var(--spacing-xs);
            left: var(--spacing-xs);
            border-top: 2px solid var(--accent-gold);
            border-left: 2px solid var(--accent-gold);
            border-radius: 2px 0 0 0;
        }

        .life-snippet-container::after {
            right: var(--spacing-xs);
            bottom: var(--spacing-xs);
            border-right: 2px solid var(--accent-gold);
            border-bottom: 2px solid var(--accent-gold);
            border-radius: 0 0 2px 0;
        }

        .snippet-header {
            display: flex;
            justify-content: flex-end;
            padding: var(--spacing-s) var(--spacing-m);
            border-bottom: 1px solid var(--border-color);
            background: linear-gradient(to bottom, rgba(212,175,55,0.05), transparent);
        }

        [data-theme="gray"] .snippet-header,
        [data-theme="dark"] .snippet-header {
            background: linear-gradient(to bottom, rgba(229,192,123,0.08), transparent);
        }

        .theme-toggle-group {
            display: flex;
            gap: var(--spacing-xs);
            background: var(--border-color);
            border-radius: 999px;
            padding: 2px;
        }

        .theme-btn {
            background: transparent;
            border: none;
            border-radius: 999px;
            padding: var(--spacing-xs) var(--spacing-s);
            cursor: pointer;
            font-size: 14px;
            color: var(--text-secondary);
            transition: all 0.2s ease;
            display: flex;
            align-items: center;
            gap: 4px;
            min-width: 60px;
            justify-content: center;
        }

        .theme-btn.active {
            background: var(--bg-card);
            color: var(--accent-gold);
            box-shadow: 0 2px 4px var(--shadow-soft);
        }

        .theme-btn:hover:not(.active) {
            background: rgba(212,175,55,0.1);
            color: var(--text-primary);
        }

        .snippet-content {
            padding: var(--spacing-xl);
            line-height: 1.8;
            font-size: 15px;
            color: var(--text-primary);
            white-space: pre-wrap;
            min-height: 100px;
            position: relative;
        }

        .snippet-content::before {
            content: '"';
            position: absolute;
            top: var(--spacing-m);
            left: var(--spacing-m);
            font-size: 48px;
            color: var(--accent-gold);
            opacity: 0.2;
            font-family: Georgia, serif;
            line-height: 1;
        }

        .snippet-footer {
            padding: var(--spacing-m) var(--spacing-xl);
            background: linear-gradient(to top, rgba(212,175,55,0.05), transparent);
            border-top: 1px solid var(--border-color);
            display: flex;
            justify-content: flex-end;
            align-items: center;
        }

        [data-theme="gray"] .snippet-footer,
        [data-theme="dark"] .snippet-footer {
            background: linear-gradient(to top, rgba(229,192,123,0.08), transparent);
        }

        .snippet-meta {
            display: flex;
            align-items: center;
            gap: var(--spacing-m);
            font-size: 13px;
            color: var(--text-secondary);
        }

        .meta-divider {
            width: 1px;
            height: 12px;
            background: var(--border-color);
        }

        @media (max-width: 480px) {
            body {
                padding: var(--spacing-s);
            }

            .snippet-content {
                padding: var(--spacing-l);
                font-size: 14px;
            }

            .snippet-footer {
                padding: var(--spacing-s) var(--spacing-l);
            }

            .theme-btn {
                min-width: auto;
                padding: var(--spacing-xs);
            }

            .theme-btn span {
                display: none;
            }
        }

        body {
            opacity: 0;
            animation: fadeIn 0.3s ease forwards;
        }

        @keyframes fadeIn {
            to {
                opacity: 1;
            }
        }
    </style>
</head>
<body>
    <div class="life-snippet-container">
        <div class="snippet-header">
            <div class="theme-toggle-group">
                <button class="theme-btn" data-theme="light" onclick="setTheme('light')">
                    ☀️<span>浅色</span>
                </button>
                <button class="theme-btn" data-theme="gray" onclick="setTheme('gray')">
                    🌤️<span>柔和</span>
                </button>
                <button class="theme-btn" data-theme="dark" onclick="setTheme('dark')">
                    🌙<span>深色</span>
                </button>
            </div>
        </div>
        <div class="snippet-content">$1</div>
        <div class="snippet-footer">
            <div class="snippet-meta">
                <span>神人大陆</span>
                <div class="meta-divider"></div>
                <span>记录于此刻</span>
            </div>
        </div>
    </div>

    <script>
        function setTheme(theme) {
            document.body.setAttribute('data-theme', theme);
            localStorage.setItem('theme', theme);

            // 更新按钮状态
            document.querySelectorAll('.theme-btn').forEach(btn => {
                if (btn.getAttribute('data-theme') === theme) {
                    btn.classList.add('active');
                } else {
                    btn.classList.remove('active');
                }
            });
        }

        function initTheme() {
            const savedTheme = localStorage.getItem('theme') || 'light';
            setTheme(savedTheme);
        }

        document.addEventListener('DOMContentLoaded', initTheme);
    </script>
</body>
</html>
